// HasSLABindings applies the HasEdge predicate on the "sla_bindings" edge.
func HasSLABindings() predicate.MSPContract {
	return predicate.MSPContract(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, SLABindingsTable, SLABindingsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSLABindingsWith applies the HasEdge predicate on the "sla_bindings" edge with a given conditions (other predicates).
func HasSLABindingsWith(preds ...predicate.MSPContractSLABinding) predicate.MSPContract {
	return predicate.MSPContract(func(s *sql.Selector) {
		step := newSLABindingsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.MSPContract) predicate.MSPContract {
	return predicate.MSPContract(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.MSPContract) predicate.MSPContract {
	return predicate.MSPContract(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.MSPContract) predicate.MSPContract {
	return predicate.MSPContract(sql.NotPredicates(p))
}
